chip Control(op1, op0, step) -> memOut, aLoad, bLoad {
  n1 = Not(op1)
  n0 = Not(op0)
  lda = And(n1, op0)
  ldb = And(op1, n0)
  swp = And(op1, op0)
  reads = Or(lda, ldb)
  memOut = And(step, reads)
  wa = Or(lda, swp)
  wb = Or(ldb, swp)
  aLoad = And(step, wa)
  bLoad = And(step, wb)
}

